#include "zebra_puzzle.h"

#include <array>

namespace zebra_puzzle {

namespace {

// Number of houses / items in each category.
constexpr int n = 5;

// Each category is represented by an array mapping item -> house index.
// For example colors[RED] == 2 means the red house is house 2.

enum Nationality { NORWEGIAN = 0, ENGLISHMAN, SPANIARD, UKRAINIAN, JAPANESE };
enum Color { RED = 0, GREEN, IVORY, YELLOW, BLUE };
enum Drink { COFFEE = 0, TEA, MILK, ORANGE_JUICE, WATER };
enum Pet { DOG = 0, SNAILS, FOX, HORSE, ZEBRA };
enum Hobby { DANCING = 0, PAINTING, READING, FOOTBALL, CHESS };

const std::string kNationalityNames[5] = {"Norwegian", "Englishman", "Spaniard",
                                          "Ukrainian", "Japanese"};

using Assignment = std::array<int, n>;

// Iterate over all permutations of {0,1,2,3,4} in place.
bool next_permutation(Assignment& a) {
    int i = n - 2;
    while (i >= 0 && a[i] >= a[i + 1]) --i;
    if (i < 0) return false;
    int j = n - 1;
    while (a[j] <= a[i]) --j;
    std::swap(a[i], a[j]);
    std::reverse(a.begin() + i + 1, a.end());
    return true;
}

Assignment initial() {
    Assignment a;
    for (int i = 0; i < n; ++i) a[i] = i;
    return a;
}

inline int adjacent(int a, int b) { return (a - b == 1) || (b - a == 1); }

}  // namespace

Solution solve() {
    for (Assignment colors = initial;;) {
        // 6: the green house is immediately right of the ivory house.
        const bool rule6 = (colors[GREEN] == colors[IVORY] + 1);
        // 15 combined with 10: norwegian (house 0) lives next to the blue house.
        const bool rule15 = (colors[BLUE] == 1);
        if (!rule6 || !rule15) {
            if (!next_permutation(colors)) break;
            continue;
        }

        for (Assignment nats = initial;;) {
            // 10: the norwegian lives in the first house.
            if (nats[NORWEGIAN] != 0) {
                if (!next_permutation(nats)) break;
                continue;
            }
            // 2: the englishman lives in the red house.
            if (nats[ENGLISHMAN] != colors[RED]) {
                if (!next_permutation(nats)) break;
                continue;
            }

            for (Assignment drinks = initial;;) {
                // 9: the middle house drinks milk.
                if (drinks[MILK] != 2) {
                    if (!next_permutation(drinks)) break;
                    continue;
                }
                // 4: the green house drinks coffee.
                if (drinks[COFFEE] != colors[GREEN]) {
                    if (!next_permutation(drinks)) break;
                    continue;
                }
                // 5: the ukrainian drinks tea.
                if (drinks[TEA] != nats[UKRAINIAN]) {
                    if (!next_permutation(drinks)) break;
                    continue;
                }

                for (Assignment hobbies = initial;;) {
                    // 8: the yellow house is a painter.
                    if (hobbies[PAINTING] != colors[YELLOW]) {
                        if (!next_permutation(hobbies)) break;
                        continue;
                    }
                    // 13: the football player drinks orange juice.
                    if (hobbies[FOOTBALL] != drinks[ORANGE_JUICE]) {
                        if (!next_permutation(hobbies)) break;
                        continue;
                    }
                    // 14: the japanese plays chess.
                    if (hobbies[CHESS] != nats[JAPANESE]) {
                        if (!next_permutation(hobbies)) break;
                        continue;
                    }

                    for (Assignment pets = initial;;) {
                        // 3: the spaniard owns the dog.
                        if (pets[DOG] != nats[SPANIARD]) {
                            if (!next_permutation(pets)) break;
                            continue;
                        }
                        // 7: the snail owner likes to go dancing.
                        if (pets[SNAILS] != hobbies[DANCING]) {
                            if (!next_permutation(pets)) break;
                            continue;
                        }
                        // 11: reading lives next to the fox.
                        if (!adjacent(hobbies[READING], pets[FOX])) {
                            if (!next_permutation(pets)) break;
                            continue;
                        }
                        // 12: the painter's house is next to the horse.
                        if (!adjacent(hobbies[PAINTING], pets[HORSE])) {
                            if (!next_permutation(pets)) break;
                            continue;
                        }

                        // All constraints satisfied: build the answer.
                        const int water_house = drinks[WATER];
                        const int zebra_house = pets[ZEBRA];

                        Solution solution;
                        for (int i = 0; i < n; ++i) {
                            if (nats[i] == water_house) solution.drinksWater = kNationalityNames[i];
                            if (nats[i] == zebra_house) solution.ownsZebra = kNationalityNames[i];
                        }
                        return solution;
                    }
                    if (!next_permutation(pets)) break;
                }
                if (!next_permutation(hobbies)) break;
            }
            if (!next_permutation(drinks)) break;
        }
        if (!next_permutation(nats)) break;
    }

    return Solution{};
}

}  // namespace zebra_puzzle

#include "zebra_puzzle.h"

#include <algorithm>
#include <array>

namespace zebra_puzzle {

namespace {

// Number of houses / number of items in each category.
constexpr int n = 5;

// A category assignment maps every item of a category to a house index,
// e.g. colors[RED] == 2 means "the red house is house 2".
using Assignment = std::array<int, n>;

enum Nationality { NORWEGIAN = 0, ENGLISHMAN, SPANIARD, UKRAINIAN, JAPANESE };
enum Color { RED = 0, GREEN, IVORY, YELLOW, BLUE };
enum Drink { COFFEE = 0, TEA, MILK, ORANGE_JUICE, WATER };
enum Pet { DOG = 0, SNAILS, FOX, HORSE, ZEBRA };
enum Hobby { DANCING = 0, PAINTING, READING, FOOTBALL, CHESS };

const std::string kNationalityNames[n] = {"Norwegian", "Englishman", "Spaniard", "Ukrainian",
                                          "Japanese"};

// The five categories, searched in this order (each level only uses constraints
// about itself and about the already assigned categories).
constexpr int kNumCategories = 5;

inline bool adjacent(int a, int b) { return (a - b == 1) || (b - a == 1); }

// Checks the rules that become testable as soon as 'level' is assigned.
// Rule 1 (five houses) is part of the model itself.
bool valid(int level, const std::array<Assignment, kNumCategories>& a) {
    const Assignment& colors = a[0];
    const Assignment& nats = a[1];
    const Assignment& drinks = a[2];
    const Assignment& hobbies = a[3];
    const Assignment& pets = a[4];

    switch (level) {
        case 0:  // colors
            // 6: the green house is immediately to the right of the ivory house.
            return colors[GREEN] == colors[IVORY] + 1;
        case 1:  // nationalities
            // 10: the norwegian lives in the first house.
            if (nats[NORWEGIAN] != 0) return false;
            // 15: the norwegian lives next to the blue house.
            if (colors[BLUE] != 1) return false;
            // 2: the englishman lives in the red house.
            if (nats[ENGLISHMAN] != colors[RED]) return false;
            return true;
        case 2:  // drinks
            // 9: the person in the middle house drinks milk.
            if (drinks[MILK] != 2) return false;
            // 4: the person in the green house drinks coffee.
            if (drinks[COFFEE] != colors[GREEN]) return false;
            // 5: the ukrainian drinks tea.
            if (drinks[TEA] != nats[UKRAINIAN]) return false;
            return true;
        case 3:  // hobbies
            // 8: the person in the yellow house is a painter.
            if (hobbies[PAINTING] != colors[YELLOW]) return false;
            // 13: the person who plays football drinks orange juice.
            if (hobbies[FOOTBALL] != drinks[ORANGE_JUICE]) return false;
            // 14: the japanese person plays chess.
            if (hobbies[CHESS] != nats[JAPANESE]) return false;
            return true;
        default:  // pets
            // 3: the spaniard owns the dog.
            if (pets[DOG] != nats[SPANIARD]) return false;
            // 7: the snail owner likes to go dancing.
            if (pets[SNAILS] != hobbies[DANCING]) return false;
            // 11: reading lives next to the house with the fox.
            if (!adjacent(hobbies[READING], pets[FOX])) return false;
            // 12: the painter's house is next to the house with the horse.
            if (!adjacent(hobbies[PAINTING], pets[HORSE])) return false;
            return true;
    }
}

// Depth first search over all permutations of the remaining categories.
bool search(int level, std::array<Assignment, kNumCategories>& a, Solution& out) {
    Assignment& perm = a[level];
    for (int i = 0; i < n; ++i) perm[i] = i;

    do {
        if (!valid(level, a)) continue;
        if (level == kNumCategories - 1) {
            // All constraints are satisfied, read the answer off the assignment.
            const int water_house = a[2][WATER];
            const int zebra_house = a[4][ZEBRA];
            for (int i = 0; i < n; ++i) {
                if (a[1][i] == water_house) out.drinksWater = kNationalityNames[i];
                if (a[1][i] == zebra_house) out.ownsZebra = kNationalityNames[i];
            }
            return true;
        }
        if (search(level + 1, a, out)) return true;
    } while (std::next_permutation(perm.begin(), perm.end()));

    return false;
}

}  // namespace

Solution solve() {
    std::array<Assignment, kNumCategories> assignments{};
    Solution solution;
    if (search(0, assignments, solution)) return solution;
    return Solution{};
}

}  // namespace zebra_puzzle
